#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N);
    vector<char> op(N - 1);

    for (int i = 0; i < N; i++) {
        cin >> A[i];
        if (i < N - 1) cin >> op[i];
    }

    // dp_max[i][j] = maximum value of subexpression from i to j (inclusive)
    // dp_min[i][j] = minimum value of subexpression from i to j (inclusive)
    vector<vector<long long>> dp_max(N, vector<long long>(N, LLONG_MIN));
    vector<vector<long long>> dp_min(N, vector<long long>(N, LLONG_MAX));

    for (int i = 0; i < N; i++) {
        dp_max[i][i] = A[i];
        dp_min[i][i] = A[i];
    }

    // length from 2 to N
    for (int len = 2; len <= N; len++) {
        for (int i = 0; i + len - 1 < N; i++) {
            int j = i + len - 1;
            for (int k = i; k < j; k++) {
                // split at k: left = [i, k], right = [k+1, j]
                if (op[k] == '+') {
                    dp_max[i][j] = max(dp_max[i][j], dp_max[i][k] + dp_max[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_max[i][k] + dp_min[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_min[i][k] + dp_max[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_min[i][k] + dp_min[k+1][j]);

                    dp_min[i][j] = min(dp_min[i][j], dp_max[i][k] + dp_max[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_max[i][k] + dp_min[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_min[i][k] + dp_max[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_min[i][k] + dp_min[k+1][j]);
                } else { // '-'
                    dp_max[i][j] = max(dp_max[i][j], dp_max[i][k] - dp_max[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_max[i][k] - dp_min[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_min[i][k] - dp_max[k+1][j]);
                    dp_max[i][j] = max(dp_max[i][j], dp_min[i][k] - dp_min[k+1][j]);

                    dp_min[i][j] = min(dp_min[i][j], dp_max[i][k] - dp_max[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_max[i][k] - dp_min[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_min[i][k] - dp_max[k+1][j]);
                    dp_min[i][j] = min(dp_min[i][j], dp_min[i][k] - dp_min[k+1][j]);
                }
            }
        }
    }

    cout << dp_max[0][N-1] << '\n';

    return 0;
}

