int main() {
    int n;
    cin >> n;

    vector<long long> A(n);
    vector<char> op(n-1);

    cin >> A[0];
    for (int i = 1; i < n; i++) {
        cin >> op[i-1] >> A[i];
    }

    long long ans = A[0];
    bool seen_minus = false;

    for (int i = 1; i < n; i++) {
        if (op[i-1] == '-') seen_minus = true;
        // Actually seen_minus should be checked before updating? No.
        // op[i-1] is between A[i-1] and A[i], so it's part of op_1..op_{i-1} (1-indexed)
        // So when considering A[i], we should have already seen op[i-1].
        // Let me re-check: seen_minus should include op[i-1] when processing A[i].
        if (seen_minus) ans += abs(A[i]);
        else ans += A[i];
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    vector<char> op(N - 1);
    for (int i = 0; i < N - 1; i++) cin >> op[i];

    // dpMax / dpMin:
    // considering the suffix starting at A[i],
    // when this suffix is evaluated as a "term" that may be preceded by
    // either + or -, what are the maximum/minimum values obtainable?
    //
    // For the last number, only A[N-1] itself.
    long long dpMax = A[N - 1];
    long long dpMin = A[N - 1];

    for (int i = N - 2; i >= 0; i--) {
        long long nMax, nMin;
        if (op[i] == '+') {
            // A[i] + (suffix)
            nMax = A[i] + dpMax;
            nMin = A[i] + dpMin;
        } else {
            // A[i] - (suffix)
            // Parentheses can make the suffix any value between dpMin and dpMax.
            nMax = A[i] - dpMin;
            nMin = A[i] - dpMax;
        }
        dpMax = nMax;
        dpMin = nMin;
    }

    cout << dpMax << '\n';
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);

    int A[N];
    char op[N]; // operators, op[i] is between A[i] and A[i+1]

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        if (i < N - 1) {
            scanf(" %c", &op[i]);
        }
    }

    long long result = A[0];
    int first_minus = -1;
    for (int i = 0; i < N - 1; i++) {
        if (op[i] == '-') {
            first_minus = i + 1;
            break;
        }
    }

    if (first_minus == -1) {
        // only plus signs
        for (int i = 1; i < N; i++) {
            result += A[i];
        }
    } else {
        for (int i = 1; i < N; i++) {
            if (i < first_minus) {
                result += A[i];
            } else if (i == first_minus) {
                result -= A[i];
            } else {
                result += llabs((long long)A[i]);
            }
        }
    }

    printf("%lld\n", result);
    return 0;
}

