#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc((N + 1) * sizeof(ll));
    char *op = (char *)malloc((N + 1) * sizeof(char));

    scanf("%lld", &A[1]);
    for (int i = 1; i <= N - 1; i++) {
        scanf(" %c %lld", &op[i], &A[i + 1]);
    }

    const ll INF = (1LL << 60);

    /* dpMax[i][s], dpMin[i][s]
       processed up to A_i.
       s = parity (mod 2) of the number of currently open parentheses
           that began after the most recent operator.
       Effective sign of A_i is determined by this parity.
       Transition:
       - before reading next term, we may close/open any parentheses at A_i,
         so only the parity matters.
       - crossing operator '+' keeps parity, '-' flips parity.
       This leads to a simple DP with 2 states.
    */

    ll dpMax[2], dpMin[2], ndpMax[2], ndpMin[2];

    dpMax[0] = dpMin[0] = A[1];
    dpMax[1] = -INF;
    dpMin[1] = INF;

    for (int i = 1; i <= N - 1; i++) {
        ndpMax[0] = ndpMax[1] = -INF;
        ndpMin[0] = ndpMin[1] = INF;

        for (int s = 0; s < 2; s++) {
            if (dpMax[s] == -INF) continue;

            int ns0, ns1;
            if (op[i] == '+') {
                ns0 = 0;
                ns1 = 1;
            } else {
                ns0 = 1;
                ns1 = 0;
            }

            /* After A_i, we can choose parity t of open parentheses.
               Then operator transforms it to next state's parity.
               If next parity is 0, A_{i+1} is added; if 1, subtracted.
            */

            /* choose t = 0 */
            {
                int ns = (op[i] == '+') ? 0 : 1;
                ll add = (ns == 0 ? A[i + 1] : -A[i + 1]);

                ndpMax[ns] = maxll(ndpMax[ns], dpMax[s] + add);
                ndpMin[ns] = minll(ndpMin[ns], dpMin[s] + add);
            }

            /* choose t = 1 */
            {
                int ns = (op[i] == '+') ? 1 : 0;
                ll add = (ns == 0 ? A[i + 1] : -A[i + 1]);

                ndpMax[ns] = maxll(ndpMax[ns], dpMax[s] + add);
                ndpMin[ns] = minll(ndpMin[ns], dpMin[s] + add);
            }
        }

        dpMax[0] = ndpMax[0];
        dpMax[1] = ndpMax[1];
        dpMin[0] = ndpMin[0];
        dpMin[1] = ndpMin[1];
    }

    /* At the end, all parentheses must be closed, so final parity is 0. */
    printf("%lld\n", dpMax[0]);

    free(A);
    free(op);
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
        }
        char[] ops = new char[N - 1];
        for (int i = 0; i < N - 1; i++) {
            ops[i] = sc.next().charAt(0);
        }

        long result = A[0];
        boolean inNegativeSegment = false;
        long segmentSum = 0;

        for (int i = 0; i < N - 1; i++) {
            if (ops[i] == '-') {
                if (inNegativeSegment) {
                    result += Math.abs(segmentSum);
                } else {
                    inNegativeSegment = true;
                }
                segmentSum = A[i + 1];
            } else { // '+'
                if (inNegativeSegment) {
                    segmentSum += A[i + 1];
                } else {
                    result += A[i + 1];
                }
            }
        }
        if (inNegativeSegment) {
            result += Math.abs(segmentSum);
        }

        System.out.println(result);
    }
}

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        char[] op = new char[n-1];
        a[0] = sc.nextLong();
        for(int i = 0; i < n-1; i++) {
            op[i] = sc.next().charAt(0);
            a[i+1] = sc.nextLong();
        }
        // Find first minus
        int firstMinus = -1;
        for(int i = 0; i < n-1; i++) {
            if(op[i] == '-') { firstMinus = i; break; }
        }
        long result = 0;
        if(firstMinus == -1) {
            for(long x : a) result += x;
        } else {
            for(int i = 0; i <= firstMinus; i++) result += a[i];
            result -= a[firstMinus+1];
            for(int i = firstMinus+2; i < n; i++) result += Math.abs(a[i]);
        }
        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long[] A = new long[N + 1];
        char[] op = new char[N + 1]; // op[i] is between A[i] and A[i+1], 1-based

        for (int i = 1; i <= N; i++) {
            A[i] = fs.nextLong();
            if (i < N) op[i] = fs.next().charAt(0);
        }

        // dp0: maximum value up to current position when currently outside any
        //      "subtracted parenthesized block"
        // dp1: maximum value up to current position when currently inside such a block
        //
        // Transition idea:
        // Expression can be transformed by choosing intervals that start right after '-'
        // and flipping all signs inside them. Nested intervals correspond to toggling state.
        //
        // If current state is outside:
        //   next term contributes +A if op is '+', and -A if op is '-'
        //   after a '-' we may also start a parenthesized block before next term,
        //   making following terms evaluated in flipped state.
        //
        // If current state is inside:
        //   operators are effectively flipped.
        //   before next term we may close the block, returning to outside state.
        //
        long NEG = Long.MIN_VALUE / 4;
        long dp0 = A[1];
        long dp1 = NEG;

        for (int i = 1; i < N; i++) {
            long ndp0 = NEG, ndp1 = NEG;

            if (op[i] == '+') {
                // Outside: + stays +
                if (dp0 != NEG) ndp0 = Math.max(ndp0, dp0 + A[i + 1]);
                // Inside: + becomes -
                if (dp1 != NEG) {
                    // stay inside
                    ndp1 = Math.max(ndp1, dp1 - A[i + 1]);
                    // close before A[i+1], then process outside
                    ndp0 = Math.max(ndp0, dp1 + A[i + 1]);
                }
            } else { // op[i] == '-'
                // Outside: - stays -
                if (dp0 != NEG) {
                    // do not open
                    ndp0 = Math.max(ndp0, dp0 - A[i + 1]);
                    // open before A[i+1], then inside means flipped sign on this term
                    ndp1 = Math.max(ndp1, dp0 + A[i + 1]);
                }
                // Inside: - becomes +
                if (dp1 != NEG) {
                    // stay inside
                    ndp1 = Math.max(ndp1, dp1 + A[i + 1]);
                    // close before A[i+1], then outside
                    ndp0 = Math.max(ndp0, dp1 - A[i + 1]);
                }
            }

            dp0 = ndp0;
            dp1 = ndp1;
        }

        System.out.println(Math.max(dp0, dp1));
    }
}
